-- Revierte el seed de ejemplo del libro y los recibos sin tocar datos
-- creados por el panel. Se borran primero los movimientos vinculados y luego
-- los recibos por sus IDs deterministas.
DELETE FROM transparency_entries
WHERE id IN (
    '00000000-0000-4000-8000-000000000101',
    '00000000-0000-4000-8000-000000000102',
    '00000000-0000-4000-8000-000000000103',
    '00000000-0000-4000-8000-000000000104',
    '00000000-0000-4000-8000-000000000105',
    '00000000-0000-4000-8000-000000000106',
    '00000000-0000-4000-8000-000000000107',
    '00000000-0000-4000-8000-000000000108'
);

DELETE FROM payment_receipts
WHERE id IN (
    '00000000-0000-4000-8000-000000000001',
    '00000000-0000-4000-8000-000000000002',
    '00000000-0000-4000-8000-000000000003',
    '00000000-0000-4000-8000-000000000004',
    '00000000-0000-4000-8000-000000000005'
);
